function isMusicNotice(s){return /배경\s*음악\s*(?:ON|OFF|켜짐|꺼짐)/i.test(clean(s));}
function toast(s){if(isMusicNotice(s))return;$('#toast').textContent=clean(s);$('#toast').classList.add('visible');clearTimeout(toast.timer);toast.timer=setTimeout(()=>$('#toast').classList.remove('visible'),2600)}
// One looping music channel and a bounded reusable effects pool.
const audioVoices=new Map();
let lastMusicError=-Infinity,musicPlayPending=false,musicBlocked=false;
const effectLastPlayed=new Map();
function persistAudio(){try{localStorage.setItem(SAVE+':audio',JSON.stringify({muted,vol}));}catch{}}
function ensureMusic(){if(!music){music=new Audio('audio/theme.wav');music.loop=true;music.preload='auto';}music.volume=vol;return music;}
function resumeMusic(userGesture=false){if(userGesture)musicBlocked=false;if(muted||musicBlocked||musicPlayPending)return;let a=ensureMusic();if(!a.paused)return;musicPlayPending=true;a.play().then(()=>{if(muted)a.pause();}).catch(()=>{musicBlocked=true;if(!muted&&time-lastMusicError>10){lastMusicError=time;toast('음악 재생을 시작하려면 설정에서 다시 켜 주세요.');}}).finally(()=>{musicPlayPending=false;});}
function stopAudio(){if(music)music.pause();for(let voices of audioVoices.values())for(let a of voices)a.pause();}
function playEffect(src){if(muted||vol<=0||time-(effectLastPlayed.get(src)??-Infinity)<.12)return;effectLastPlayed.set(src,time);let voices=audioVoices.get(src);if(!voices){voices=[];audioVoices.set(src,voices);}let active=0;for(let list of audioVoices.values())for(let v of list)if(!v.paused&&!v.ended)active++;if(active>=8)return;let a=voices.find(v=>v.paused||v.ended);if(!a){if(voices.length>=2)return;a=new Audio(src);a.preload='auto';voices.push(a);}a.volume=vol;a.currentTime=0;a.play().catch(()=>{});}
function sound(n){playEffect('audio/'+n+'.wav');}
function originalSound(e){if(e.id===47){resumeMusic();return;}let src=world.originalAudio?.[e.id];if(src)playEffect(src);}
function setAudioVolume(value){vol=Math.max(0,Math.min(.7,Number(value)||0));if(music)music.volume=vol;for(let voices of audioVoices.values())for(let a of voices)a.volume=vol;persistAudio();}
