function drawHero(c,x,y,h,scale=1,anim=0,angle=0,isEnemy=false){if(originalGraphics&&h.type!==undefined&&drawOriginal(c,h.type,x,y,scale,anim,angle))return;c.save();c.translate(x,y);c.scale(scale,scale);c.fillStyle='#07191255';c.beginPath();c.ellipse(0,4,12,5,0,0,7);c.fill();let step=Math.sin(anim)*3;c.fillStyle=h.cape;c.beginPath();c.moveTo(-7,-20);c.lineTo(8,-20);c.lineTo(11+Math.sin(anim)*2,0);c.lineTo(-10,0);c.closePath();c.fill();c.strokeStyle='#26342f';c.lineWidth=4;c.beginPath();c.moveTo(-4,-4);c.lineTo(-5+step,3);c.moveTo(4,-4);c.lineTo(5-step,3);c.stroke();c.fillStyle=h.color;c.strokeStyle='#253632';c.lineWidth=1.1;c.beginPath();c.roundRect(-7,-22,14,17,3);c.fill();c.stroke();c.fillStyle='#d2b18c';c.beginPath();c.arc(0,-28,6,0,7);c.fill();if(h.weapon==='staff'){c.fillStyle=h.cape;c.beginPath();c.moveTo(-8,-30);c.lineTo(0,-44);c.lineTo(8,-30);c.closePath();c.fill()}else{c.fillStyle=h.color;c.beginPath();c.arc(0,-29,7,Math.PI,0);c.lineTo(7,-24);c.lineTo(-7,-24);c.fill();c.fillStyle='#20332e';c.fillRect(-5,-28,10,2);if(h.weapon==='greatsword'){c.fillStyle='#b45945';c.fillRect(-2,-40,4,8)}}c.strokeStyle=h.color;c.lineWidth=4;c.beginPath();c.moveTo(-6,-19);c.lineTo(-11,-10);c.moveTo(6,-19);c.lineTo(11,-11);c.stroke();c.save();c.translate(11,-15);c.rotate(angle*.2+Math.sin(anim*.5)*.1);if(h.weapon==='bow'){c.strokeStyle='#bda06a';c.lineWidth=2;c.beginPath();c.arc(0,0,13,-1.5,1.5);c.stroke();c.strokeStyle='#dfd3af';c.lineWidth=.7;c.beginPath();c.moveTo(1,-13);c.lineTo(1,13);c.stroke()}else if(h.weapon==='gun'){c.fillStyle='#534a3c';c.fillRect(-2,-4,18,6);c.fillStyle='#b4b7a9';c.fillRect(8,-5,14,5)}else if(h.weapon==='staff'){c.strokeStyle='#806346';c.lineWidth=3;c.beginPath();c.moveTo(0,10);c.lineTo(0,-22);c.stroke();c.fillStyle='#c6dfbf';c.beginPath();c.arc(0,-23,4,0,7);c.fill()}else if(h.weapon==='hammer'){c.fillStyle='#ae9051';c.fillRect(-1,-13,3,25);c.fillStyle='#d4d4b9';c.fillRect(-6,-18,14,9)}else{c.fillStyle='#d9dfce';let l=h.weapon==='greatsword'?31:23;c.beginPath();c.moveTo(-2,4);c.lineTo(-3,-l);c.lineTo(1,-l-5);c.lineTo(4,-l);c.lineTo(3,4);c.fill();c.fillStyle='#a58a49';c.fillRect(-7,0,15,3)}c.restore();if(isEnemy){c.fillStyle='#b2644e';c.fillRect(-8,-45,16,2)}c.restore()}
function castle(c,x,y,size=1,hostile=false,name=''){c.save();c.translate(x,y);c.scale(size,size);const roof=hostile?'#764b47':'#58727a';c.fillStyle='#0b1e1850';c.beginPath();c.ellipse(0,15,63,22,0,0,7);c.fill();c.fillStyle='#a9ac98';c.strokeStyle='#566356';c.lineWidth=1.5;c.beginPath();c.moveTo(-46,6);c.lineTo(-46,-38);c.lineTo(42,-38);c.lineTo(48,6);c.closePath();c.fill();c.stroke();for(let i=-42;i<45;i+=14){c.fillStyle=i%3?'#c3c4ac':'#adb39b';c.fillRect(i,-40,9,9)}c.strokeStyle='#8d967f';c.lineWidth=.7;for(let y2=-30;y2<5;y2+=9){c.beginPath();c.moveTo(-44,y2);c.lineTo(44,y2);c.stroke();for(let x2=-40;x2<45;x2+=15){c.beginPath();c.moveTo(x2+(y2%2?7:0),y2);c.lineTo(x2+(y2%2?7:0),y2+8);c.stroke()}}c.fillStyle='#2d352c';c.beginPath();c.arc(0,-9,11,Math.PI,0);c.lineTo(11,8);c.lineTo(-11,8);c.fill();c.fillStyle='#725e40';c.fillRect(-8,-8,16,17);c.strokeStyle='#343e31';for(let x2=-6;x2<9;x2+=4){c.beginPath();c.moveTo(x2,-10);c.lineTo(x2,8);c.stroke()}for(let tx of [-42,42]){c.fillStyle='#c2c3ac';c.fillRect(tx-12,-65,24,65);c.fillStyle='#929b85';c.fillRect(tx+6,-65,6,65);c.fillStyle=roof;c.beginPath();c.moveTo(tx-17,-65);c.lineTo(tx,-91);c.lineTo(tx+17,-65);c.fill();c.fillStyle='#36453a';c.fillRect(tx-3,-54,6,10);c.strokeStyle='#8e967e';for(let ty=-40;ty<0;ty+=12){c.beginPath();c.moveTo(tx-12,ty);c.lineTo(tx+11,ty);c.stroke()}}c.fillStyle='#c8c8ad';c.fillRect(-20,-75,40,34);c.fillStyle=roof;c.beginPath();c.moveTo(-25,-75);c.lineTo(0,-103);c.lineTo(25,-75);c.fill();c.strokeStyle='#b4a77e';c.lineWidth=2;c.beginPath();c.moveTo(0,-100);c.lineTo(0,-122);c.stroke();c.fillStyle=hostile?'#a95547':'#bcac6e';c.beginPath();c.moveTo(1,-121);c.lineTo(21,-116+Math.sin(time*2)*2);c.lineTo(1,-110);c.fill();c.fillStyle='#4d5b4e';c.fillRect(-10,-65,5,9);c.fillRect(6,-65,5,9);c.restore()}
