function tileKind(t){const g=t>>4;if(g<=1)return 0;if(g<=3)return 1;if(g<=5)return 2;if(g<=7)return 3;if(g<=9)return 4;if(g<=13)return 5;if(g<=17)return 6;if(g<=23)return 7;if(g<=35)return 8;if(g>=1440&&g<1490)return 6;if(g>=1500&&g<1570)return 7;if(g>=400&&g<450)return 5;return 9}
