function tickOriginalEvents(dt){if(!scxEngine)return;
 for(let e of entities){if(!e.alive||!e.scxOrder||e.type>=106)continue;let orderDt=dt;if(Math.abs(e.x-player.x)>1100||Math.abs(e.y-player.y)>1100){e.orderAccum=(e.orderAccum||0)+dt;if(e.orderAccum<.2)continue;orderDt=e.orderAccum;e.orderAccum=0;}let target=e.scxOrder,dx=target.x-e.x,dy=target.y-e.y,d=Math.hypot(dx,dy);if(d<20){e.scxOrder=null;e.vx=e.vy=0;}else if(!e.hostile||Math.hypot(e.x-player.x,e.y-player.y)>620)steerGround(e,dx/d*90,dy/d*90,orderDt,true);}
 scxTick+=dt;if(scxTick<.1)return;let step=scxTick;scxTick=0;
 for(let u of scxUnits)if(u.browserExpire&&u.browserExpire<=clock&&u.alive!==false){scxEngine.kill(u);let e=entities.find(e=>e.scxId===u.id);if(e)e.alive=false;}let nativeById=new Map(scxUnits.map(u=>[u.id,u])),renderById=new Map();
 for(let e of entities){if(e.scxHidden||!e.placed&&e.scxId===undefined)continue;let id=e.scxId??e.id;renderById.set(id,e);let u=nativeById.get(id);if(u){u.x=e.x;u.y=e.y;u.hp=e.health;u.alive=e.alive;u.browserBoss=e.bossAI;}}
 let knight=nativeById.get(scxActorId);if(knight){knight.x=player.x;knight.y=player.y;knight.hp=player.hp;knight.maxHp=player.maxHp;knight.alive=deathTimer<=0;}
 scxEngine.putVal(scxEngine.resources,1,0,Math.floor(player.gold));scxEngine.step(Math.min(200,step*1000));
 for(let u of scxUnits){if(u.id===scxActorId){if(u.alive===false||u.hp<=0){if(deathTimer<=0)damagePlayer(player.hp+player.armor+1,true);}else if(knight){if(Math.hypot(u.x-player.x,u.y-player.y)>1){let dest=nearestWalkable(u.x,u.y);player.x=dest.x;player.y=dest.y;route=[];}player.hp=Math.min(player.maxHp,u.hp);}continue;}
 if(u.x>=8192||u.x>=7780&&!bossProfiles[u.type]||u.y<=1480||u.type>=203){let hidden=renderById.get(u.id);if(hidden){hidden.alive=false;hidden.scxHidden=true;}continue;}let e=renderById.get(u.id);
 if(!e&&u.alive!==false&&u.hp>0){let st=world.stats[u.type]||{};let point=solidBuilding(u.type)?{x:u.x,y:u.y}:nearestWalkable(u.x,u.y);e={...u,x:point.x,y:point.y,id:'scx'+u.id,scxId:u.id,name:short(st.name||''),health:u.hp,maxHealth:u.maxHp||u.hp,alive:true,hostile:u.owner>=6&&u.owner<=7,cd:0,anim:0};entities.push(e);renderById.set(u.id,e);}
 if(!e)continue;if(u.x!==e.x||u.y!==e.y){let dest=solidBuilding(u.type)?{x:u.x,y:u.y}:nearestWalkable(u.x,u.y);e.x=dest.x;e.y=dest.y;}
 e.scxHidden=false;e.health=u.hp;e.maxHealth=u.maxHp||e.maxHealth;e.alive=u.alive!==false&&u.hp>0;e.owner=u.owner;e.type=u.type;e.invincible=!!u.invincible;e.gateOpen=u.doodadState===5;e.hostile=isHostile(e);e.boss=e.hostile&&campaigns.some(c=>c.boss===e.type);e.scxOrder=u.order;e.bossAI=u.browserBoss||e.bossAI;
 e.appear=Math.max(0,(e.appear||0)-step);
 }
 boss=null;let bossDistance=Infinity;for(let e of entities)if(e.alive&&e.boss&&isHostile(e)){let d=targetDistance(e);if(d<bossDistance){boss=e;bossDistance=d;}}
 rebuildSpatial();
 if(scxUnits.length>2500){scxUnits=scxUnits.filter(u=>u.alive!==false&&u.hp>0||u.id===scxActorId);scxEngine.units=scxUnits;scxEngine.typeIndex=null;scxEngine.invalidateUnits();}
 if(entities.length>2000)entities=entities.filter(e=>e.alive||e.placed);
}
function installTouchMovement(){if(floatingControls||typeof installKingZeroControls==='undefined')return;floatingControls=installKingZeroControls({gameElement:C,enabled:()=>started&&!paused&&deathTimer<=0,keyboard:false,onMove(x,y){if(!started||paused)return;joy.x=x;joy.y=y;joy.active=Math.hypot(x,y)>.01;}});}
function upgradePanel(){const native=world.nativeUnits[heroes[selected].type];player.upgrades??={};let rows=[['무기',native.attackUpgrade],['방어구',native.armorUpgrade]].filter(r=>Number.isInteger(r[1])&&r[1]<16);modal(titleRow('업그레이드')+`<p>보유 금화 ${Math.floor(player.gold).toLocaleString()} GOLD</p><p class="fine">비용과 최대 단계는 원본 맵 UPGx와 PUPx 값입니다. 기사 한 명의 전투 능력치에 적용됩니다.</p><div class="list">${rows.map(([name,id])=>{let data=world.upgrades[id],level=player.upgrades[id]??data.start,cost=data.base+data.factor*level;return `<div class="entry"><div class="row"><h3>${name} ${level}단계 / 최대 ${data.max}단계</h3><button onclick="buyUpgrade(${id})" ${level>=data.max||player.gold<cost?'disabled':''}>${level>=data.max?'최대 단계':cost.toLocaleString()+' GOLD'}</button></div><p>${id===native.attackUpgrade?'공격력 '+player.damage:'방어력 '+player.armor}</p></div>`}).join('')}</div>`)}
function buyUpgrade(id){let n=world.nativeUnits[heroes[selected].type];if(![n.attackUpgrade,n.armorUpgrade].includes(id))return;let d=world.upgrades[id];player.upgrades??={};let level=player.upgrades[id]??d.start,cost=d.base+d.factor*level;if(level>=d.max||player.gold<cost)return;player.gold-=cost;player.upgrades[id]=level+1;if(id===n.attackUpgrade)player.damage+=n.bonus||1;else player.armor++;saveGame();upgradePanel();toast('업그레이드 '+(level+1)+'단계 완료');}
function originalEventsPanel(){let stats=scxEngine?.status(),messages=(scxEngine?.messages||[]).filter(m=>!isMusicNotice(m.text)&&!/[=]{4}/.test(m.text)&&(m.player===0||m.player===1)).filter((m,i,rows)=>rows.findLastIndex(v=>v.id===m.id&&v.player===m.player)===i);modal(titleRow('원본 사건')+`<p>마을과 성 근처에서 수비대를 처치한 뒤 대화 버튼이 점령으로 바뀌면 누르세요. 4초간 자리를 지키면 원본 조건에 따라 소유권이 이전됩니다.</p><div class="actions"><button onclick="bossGuidePanel()">보스 기술 안내</button></div><div class="note">조건 검사에 따라 실제 실행된 사건을 표시합니다.<br>원본 사건 ${stats?.total||0}개 / 실행 ${stats?.executions||0}회 / 대사 ${messages.length}개<br>실행 오류 ${stats?.errors||0}개 / 미지원 행동 ${stats?.unsupported||0}개</div><div class="list" style="margin-top:16px">${messages.slice(-80).reverse().map(m=>`<div class="entry"><small>사건 ${m.trigger} / ${Math.floor(m.time/1000)}초</small><p style="white-space:pre-line">${esc(clean(m.text))}</p></div>`).join('')||'<p>아직 발생한 대사가 없습니다.</p>'}</div>`)}

// Capture executes the original region/guard conditions and ownership actions after a visible hold.
let captureRules=[],captureRuleIds=new Set(),captureState=null,captureReady=null;
const captureCoreTypes=new Set([112,172,163,190,174,154,200,126]);
function initCaptureRules(){captureRules=(scxData?.triggers||[]).filter(t=>t.conditions.some(c=>!(c.flags&2)&&c.type===3&&c.player===13&&c.unit===230&&c.comparison===0&&c.value>0)&&t.actions.some(a=>!(a.flags&2)&&a.type===48&&a.value===13));captureRuleIds=new Set(captureRules.map(t=>t.id));}
function nearbyCapture(){if(!scxEngine||deathTimer||!player)return null;let core=entities.filter(e=>e.alive&&captureCoreTypes.has(e.type)&&e.owner!==1&&(isHostile(e)||e.owner===11)&&targetDistance(e)<140),best=null,bestDistance=Infinity;for(let e of core)for(let rule of captureRules){let action=rule.actions.find(a=>!(a.flags&2)&&a.type===48&&a.value===13&&scxEngine.matchesType(e,a.unit)&&scxEngine.inLoc(e,scxEngine.loc(a.location)));if(!action)continue;let distance=targetDistance(e);let score=distance+(captureConditions(rule)?0:10000);if(score<bestDistance){best={target:e,rule};bestDistance=score;}}return best;}
function captureConditions(rule){let knight=scxUnits.find(u=>u.id===scxActorId);if(knight){knight.x=player.x;knight.y=player.y;}scxEngine.invalidateUnits();return rule.conditions.every(c=>scxEngine.condition(c,1));}
function startCapture(candidate=nearbyCapture()){if(!candidate||paused||deathTimer)return false;if(!captureConditions(candidate.rule)){toast('점령 조건이 충족되지 않았습니다. 지역의 적 병력과 방어탑, 관련 임무를 확인하세요.');return false;}captureReady=null;captureState={ruleId:candidate.rule.id,targetId:candidate.target.id,elapsed:0,x:player.x,y:player.y};toast('4초 동안 이 자리를 지키면 점령합니다.');return true;}
function updateCapture(dt){if(!captureState||!scxEngine)return;let state=captureState,e=entities.find(e=>e.id===state.targetId),rule=captureRules.find(t=>t.id===state.ruleId);if(e?.owner===1){captureState=null;captureReady=null;rebuildSpatial();toast(e.name+' 점령 완료');saveGame();return;}if(!e?.alive||!rule||deathTimer||Math.hypot(player.x-state.x,player.y-state.y)>12||targetDistance(e)>140||!captureConditions(rule)){captureState=null;captureReady=null;toast('점령이 취소됐습니다.');return;}state.elapsed+=dt;if(state.elapsed>=4)captureReady=rule.id;}

