function updateBossSkills(e,dt){if(!e.alive||!isHostile(e)||deathTimer||Math.hypot(e.x-player.x,e.y-player.y)>620)return;let profile=bossProfiles[e.type];if(!profile)return;let ai=e.bossAI??={cooldown:2,next:0,casts:0};if(ai.castingUntil>clock)return;ai.cooldown-=dt;if(ai.cooldown>0)return;let index=ai.next%profile.length,skill=profile[index],phase=e.health<e.maxHealth*.5?2:1;ai.next++;ai.casts++;ai.cooldown=skill[4]*(phase===2?.75:1);ai.castingUntil=clock+skill[3];e.attackStart=time;e.attackUntil=time+skill[3];let point=['circle','drain','dash'].includes(skill[1])?{x:player.x,y:player.y}:{x:e.x,y:e.y};effects.push({x:point.x,y:point.y,sx:e.x,sy:e.y,angle:Math.atan2(player.y-e.y,player.x-e.x),r:skill[2],life:skill[3],max:skill[3],kind:'danger',color:index?'#bb88e5':'#f19561',bossCast:true,sourceId:e.id,label:skill[0],skillKind:skill[1],power:skill[5],phase});}
function resolveBossSkill(f){let source=entities.find(e=>e.id===f.sourceId&&e.alive&&isHostile(e));if(!source||deathTimer)return;let kind=f.skillKind;
 if(kind==='heal'){source.health=Math.min(source.maxHealth,source.health+source.maxHealth*f.power);particle(source.x,source.y-50,'회복','#9dd7a5');return;}
 if(kind==='shield'){source.bossAI.shieldUntil=clock+f.power;particle(source.x,source.y-50,'피해 감소','#acbbe9');return;}
 if(kind==='summon'){spawnBossMinions(source);return;}
 if(kind==='dash'&&!solidBuilding(source.type)){let safe=nearestWalkable(f.x,f.y);moveGround(source,safe.x-source.x,safe.y-source.y);}
 let hits=(x,y)=>{if(kind==='line'){let dx=x-f.sx,dy=y-f.sy,along=dx*Math.cos(f.angle)+dy*Math.sin(f.angle),across=Math.abs(-dx*Math.sin(f.angle)+dy*Math.cos(f.angle));return along>=-25&&along<=f.r&&across<=48;}return Math.hypot(x-f.x,y-f.y)<f.r;};
 let damage=f.power*(f.phase===2?1.25:1);if(hits(player.x,player.y)){let hp=player.hp;damagePlayer(damage);if(kind==='drain'&&player.hp<hp)source.health=Math.min(source.maxHealth,source.health+(hp-player.hp)*3);}
 for(let ally of entities){if(!ally.alive||!ally.ally||!hits(ally.x,ally.y))continue;ally.health-=damage;if(ally.health<=0)ally.alive=false;}
 effects.push({x:f.x,y:f.y,r:f.r,life:.4,max:.4,color:f.color,kind:'ring'});
}
function spawnBossMinions(source){if(!scxEngine)return;let active=scxUnits.filter(u=>u.alive!==false&&u.hp>0&&u.browserSummoner===source.id).length;if(active>=4)return;for(let i=0;i<Math.min(2,4-active);i++){let p=nearestWalkable(source.x+Math.cos(i*Math.PI)*65,source.y+Math.sin(i*Math.PI)*65),type=source.type===81?38:51,hp=Math.min(1500,180+player.level*30);scxUnits.push({id:scxEngine.nextUnitId++,type,owner:source.owner,x:p.x,y:p.y,hp,maxHp:hp,alive:true,browserSummoner:source.id,browserExpire:clock+35});}scxEngine.typeIndex=null;scxEngine.invalidateUnits();}

function bossGuidePanel(){modal(titleRow('보스 기술 안내')+'<p>원본 보스에 연결한 브라우저판 전투 패턴입니다. 경고 범위가 사라지기 전에 피하세요. 체력이 절반 이하가 되면 기술 재사용 시간이 짧아집니다.</p><div class="list">'+Object.entries(bossProfiles).map(([type,skills])=>'<div class="entry"><h3>'+esc(short(world.stats[type]?.name||type))+'</h3>'+skills.map(s=>'<p>'+esc(s[0])+' / 준비 '+s[3]+'초 / 재사용 '+s[4]+'초</p>').join('')+'</div>').join('')+'</div>');}
